// src/components/SvgFlow.js
import React, { useRef, useEffect } from "react";
import * as d3 from "d3";

function parseCodeToGraph(code = "") {
  // very small heuristic parser for simple function + if/else + console.log patterns
  const nodes = [];
  const edges = [];

  if (!code || !code.trim()) return { nodes, edges };

  const fnMatch = code.match(/function\s+(\w+)\s*\(([^)]*)\)/) || code.match(/const\s+(\w+)\s*=\s*\(([^)]*)\)\s*=>/);
  const fnName = fnMatch ? fnMatch[1] : "fn";
  const param = fnMatch ? fnMatch[2].trim() : "";

  nodes.push({ id: "start", label: "Start", type: "start" });
  nodes.push({ id: "fn", label: `${fnName}(${param})`, type: "process" });

  let hasCondition = /if\s*\(/.test(code);
  if (hasCondition) {
    const condMatch = code.match(/if\s*\(([^)]+)\)/);
    const cond = condMatch ? condMatch[1].trim() : "cond";
    nodes.push({ id: "cond", label: cond, type: "condition" });

    // try to extract console.log inside if and else
    const trueLog = code.match(/if\s*\([\s\S]*?\)\s*\{\s*([\s\S]*?)\}/)?.[1].match(/console\.log\([^\)]*\)/)?.[0] || "true";
    const elseLog = code.match(/else\s*\{\s*([\s\S]*?)\}/)?.[1]?.match(/console\.log\([^\)]*\)/)?.[0] || "false";

    nodes.push({ id: "true", label: trueLog, type: "process" });
    nodes.push({ id: "false", label: elseLog, type: "process" });
    nodes.push({ id: "end", label: "End", type: "end" });

    edges.push({ from: "start", to: "fn" });
    edges.push({ from: "fn", to: "cond" });
    edges.push({ from: "cond", to: "true", label: "Yes" });
    edges.push({ from: "cond", to: "false", label: "No" });
    edges.push({ from: "true", to: "end" });
    edges.push({ from: "false", to: "end" });
  } else {
    nodes.push({ id: "end", label: "End", type: "end" });
    edges.push({ from: "start", to: "fn" });
    edges.push({ from: "fn", to: "end" });
  }

  return { nodes, edges };
}

function SvgFlow({ graph, code }) {
  const svgRef = useRef();

  useEffect(() => {
    const g = graph && graph.nodes && graph.nodes.length ? graph : parseCodeToGraph(code);
    const svgEl = d3.select(svgRef.current);
    svgEl.selectAll("*").remove(); // clear old diagram

    if (!g.nodes || !g.nodes.length) {
      // show placeholder text
      svgEl
        .append("text")
        .attr("x", 20)
        .attr("y", 30)
        .attr("fill", "#6b7280")
        .style("font-size", "14px")
        .text('No flowchart yet — click "Generate Flowchart"');
      return;
    }

    const width = Math.max(800, svgRef.current.parentElement?.clientWidth || 900);
    const nodeWidth = 220;
    const nodeHeight = 60;
    const verticalGap = 90;

    svgEl.attr("width", "100%").attr("height", g.nodes.length * verticalGap + 100);

    // simple top-to-bottom layout: center all nodes horizontally
    g.nodes.forEach((n, i) => {
      n.x = width / 2;
      n.y = 40 + i * verticalGap;
    });

    // markers for arrows
    svgEl
      .append("defs")
      .append("marker")
      .attr("id", "arrow")
      .attr("viewBox", "0 0 10 10")
      .attr("refX", 10)
      .attr("refY", 5)
      .attr("markerWidth", 6)
      .attr("markerHeight", 6)
      .attr("orient", "auto")
      .append("path")
      .attr("d", "M 0 0 L 10 5 L 0 10 z")
      .attr("fill", "#374151");

    // draw edges
    const edgeGroup = svgEl.append("g").attr("class", "edges");
    g.edges.forEach((e) => {
      const from = g.nodes.find((n) => n.id === e.from);
      const to = g.nodes.find((n) => n.id === e.to);
      if (!from || !to) return;

      // straight vertical/curved path
      const startX = from.x;
      const startY = from.y + nodeHeight / 2;
      const endX = to.x;
      const endY = to.y - nodeHeight / 2;

      const path = `M ${startX} ${startY} C ${startX} ${(startY + endY) / 2} ${endX} ${(startY + endY) / 2} ${endX} ${endY}`;

      edgeGroup
        .append("path")
        .attr("d", path)
        .attr("fill", "none")
        .attr("stroke", "#374151")
        .attr("stroke-width", 2)
        .attr("marker-end", "url(#arrow)");

      if (e.label) {
        // label mid-point
        edgeGroup
          .append("text")
          .attr("x", (startX + endX) / 2 + 10)
          .attr("y", (startY + endY) / 2 - 6)
          .attr("fill", "#374151")
          .style("font-size", "12px")
          .text(e.label);
      }
    });

    // draw nodes
    const nodeGroup = svgEl.append("g").attr("class", "nodes");
    const gNodes = nodeGroup.selectAll(".node").data(g.nodes).enter().append("g").attr("class", "node");

    // shapes
    gNodes.each(function (d) {
      const node = d3.select(this);
      const x = d.x - nodeWidth / 2;
      const y = d.y - nodeHeight / 2;

      if (d.type === "condition") {
        // diamond centered at (d.x, d.y)
        const cx = d.x;
        const cy = d.y;
        const w = nodeWidth / 2;
        const h = nodeHeight / 2;
        const points = [
          [cx, cy - h],
          [cx + w, cy],
          [cx, cy + h],
          [cx - w, cy],
        ]
          .map((p) => p.join(","))
          .join(" ");
        node
          .append("polygon")
          .attr("points", points)
          .attr("fill", "#e6f4ff")
          .attr("stroke", "#0284c7")
          .attr("stroke-width", 2)
          .attr("rx", 6);
        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y + 5)
          .attr("text-anchor", "middle")
          .attr("fill", "#0f172a")
          .style("font-size", "13px")
          .text(d.label);
      } else {
        node
          .append("rect")
          .attr("x", x)
          .attr("y", y)
          .attr("width", nodeWidth)
          .attr("height", nodeHeight)
          .attr("rx", 8)
          .attr("fill", d.type === "start" || d.type === "end" ? "#f8fafc" : "#ffffff")
          .attr("stroke", "#cbd5e1")
          .attr("stroke-width", 1.5)
          .attr("filter", "none");

        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y + 6)
          .attr("text-anchor", "middle")
          .attr("fill", "#0f172a")
          .style("font-size", "13px")
          .text(d.label);
      }
    });
  }, [graph, code]);

  return (
    <div style={{ background: "#fff", padding: "18px", borderRadius: "12px", boxShadow: "0 2px 6px rgba(0,0,0,0.06)" }}>
      <svg ref={svgRef} style={{ width: "100%", height: "100%" }}></svg>
    </div>
  );
}

export default SvgFlow;
